using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Windows.Forms;
namespace NightLens {
static class V4Tests {
    static void Snapshot(Form form,string path){form.Show();Application.DoEvents();using(var image=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(path,System.Drawing.Imaging.ImageFormat.Png);}}
    public static void Run(Forecast f,DateTime now,string[] args,List<string> log){Action<bool,string> check=(ok,message)=>{if(!ok)throw new Exception(message);log.Add("PASS: "+message);};var s=new Settings{WindowsLocation=false};var n=new Night(s,f,now);string notice;var catalog=CatalogLibrary.Load(s,out notice);var east=catalog.Where(t=>ImagingGroups.Region(t)=="Eastern Veil").ToList();check(east.Count>=2,"Eastern Veil catalog components identified");var western=catalog.First(t=>ImagingGroups.Identity(t.Canonical)=="NGC6960");var synthetic=east.Select((t,i)=>new Pick{Target=t,Score=100-i}).Concat(new[]{new Pick{Target=western,Score=80}});var grouped=ImagingGroups.Unique(synthetic,s.Rigs[0]).ToList();check(grouped.Count==2&&grouped.Count(p=>p.Target.Name.Contains("NGC6992 / NGC6995"))==1,"Eastern Veil appears once with both identifiers while Western Veil stays separate");check(n.Picks.Select(p=>ImagingGroups.Region(p.Target)??p.Target.Canonical??p.Target.Name).Distinct().Count()==n.Picks.Count,"Recommended imaging regions have no repeated entries");check(ImagingGroups.Identity("NGC 006992")=="NGC6992"&&ImagingGroups.Identity("m 027")=="M27","Alias identifiers normalize case, spacing and leading zeros");
        string oldRoot=CatalogLibrary.BuiltIn;string temp=Path.Combine(Path.GetDirectoryName(Path.GetFullPath(args[4])),"alias-fixtures");Directory.CreateDirectory(temp);try{File.WriteAllText(Path.Combine(temp,"A.csv"),"Name,Type,RAHours,DecDegrees,MajorArcmin,MinorArcmin,CanonicalId,Aliases\nDumbbell,Nebula,19.993,22.72,8,6,NGC06853,M27\n");File.WriteAllText(Path.Combine(temp,"B.csv"),"Name,Type,RAHours,DecDegrees,MajorArcmin,MinorArcmin,CanonicalId,Aliases\nMessier 27,Nebula,19.993,22.72,8,6,M 027,NGC6853\n");CatalogLibrary.BuiltIn=temp;var choices=new Settings{EnabledCatalogs=new List<string>{"A.csv","B.csv"}};check(CatalogLibrary.Load(choices,out notice).Count==1,"Cross-catalog aliases merge even when primary identifiers differ");}finally{CatalogLibrary.BuiltIn=oldRoot;}
        var site=SkySite.At(s);check(site!=null&&site.Bortle==8.9&&site.AreaEstimate,"Centennial model is labeled Bortle 8.9 area estimate");var travel=new Settings{Lat=40.5,Lon=-105.5};check(SkySite.At(travel)==null,"Sky brightness from Centennial is not reused at a distant location");var saved=Json.Read<Settings>(Json.Write(s));check(saved.SkySites[0].Bortle==8.9,"Site brightness survives settings serialization");
        var target=new Target("Test galaxy","Galaxy",1,30,30,20){Canonical="TestGalaxy",Magnitude=9};var pick=new Pick{Target=target,Fit="Fits one frame",Alt=70,Start=n.Dark.First(),End=n.Dark.Last()};var rig=s.Rigs[1];rig.Mount="Equatorial / tracker";var dark=new Settings{SkySites=new List<SkySite>{new SkySite{Lat=s.Lat,Lon=s.Lon,Bortle=3,RadiusKm=1}}};var urban=new Settings();var a=CapturePlanning.For(pick,rig,dark,n);var b=CapturePlanning.For(pick,rig,urban,n);check(b.MinHours>a.MinHours&&b.SubSeconds<=a.SubSeconds,"Brighter broadband sky increases total-time goal and shortens starting subs");check(a.Gain.StartsWith("200")&&b.Gain.StartsWith("200"),"ASI585MC Pro gain guidance follows current HCG 200 preset rather than scaling gain with Bortle");
        var seestar=s.Rigs[0];foreach(string mount in new[]{"Alt-az / smart telescope","Equatorial / tracker"}){seestar.Mount=mount;foreach(int level in Enumerable.Range(1,9)){s.SkySites[0].Bortle=level;var guide=CapturePlanning.For(pick,seestar,s,n);check(guide.SubSeconds.HasValue&&new[]{10.0,20,30}.Contains(guide.SubSeconds.Value)&&guide.Gain.Contains("not adjustable"),"S50 plan stays in app-supported 10/20/30 s with app-controlled gain (B"+level+", "+mount+")");}}
        var other=new Rig{Name="Custom smart",Camera="Built-in",CaptureModel="Other smart telescope",AllowedSubs="5,15,45",Focal=250,Aperture=50,Mount="Equatorial / tracker"};var g=CapturePlanning.For(pick,other,s,n);check(g.SubSeconds.HasValue&&new[]{5.0,15,45}.Contains(g.SubSeconds.Value)&&g.Gain.Contains("not adjustable"),"Other smart telescopes use only their entered app exposure options");other.AllowedSubs="";check(CapturePlanning.For(pick,other,s,n).SubSeconds==null,"Unknown smart-telescope app capabilities do not get invented exposure options");
        var moon=new Pick{Target=new Target("Moon","Moon",0,0,30,30){Body=CosineKitty.Body.Moon},Start=pick.Start,End=pick.End};var lunar=CapturePlanning.For(moon,seestar,s,n);check(lunar.SubSeconds==null&&lunar.Exposure.Contains("Lunar"),"S50 lunar guidance uses its lunar mode rather than a 10-second DSO frame");var cluster=new Pick{Target=new Target("Bright cluster","Open cluster",1,30,20,20){Canonical="TestCluster",Magnitude=6},Fit="Fits one frame",Alt=60,Start=pick.Start,End=pick.End};check(CapturePlanning.For(cluster,seestar,s,n).Beginner,"Suitable bright cluster receives a beginner star marker");var missing=new Settings{SkySites=new List<SkySite>()};check(CapturePlanning.For(pick,seestar,missing,n).Integration.Contains("Set site Bortle"),"Missing site class requests input instead of fabricating total integration");
        s=new Settings{WindowsLocation=false};string folder=Path.GetDirectoryName(args[3]);using(var form=new BortleForm(s))Snapshot(form,Path.Combine(folder,"Sky brightness preview.png"));using(var form=CaptureUI.Create(n.Picks.First(p=>p.Guide.Beginner).Guide))Snapshot(form,Path.Combine(folder,"Capture plan preview.png"));check(true,"Bortle settings and capture plan rendered successfully");
    }
}
}

